usage:
This `VoidEchoProjectile` script defines the projectile's behavior and appearance. To use it:

**1. Player Setup (Firing and Screen Feedback):**
   a.  **Player Script (`Player.gd` or similar):**
       gdscript
       # PLAYER_IDENTITY_TREMOR_SHADER_CODE (for a CanvasItem ShaderMaterial)
       const PLAYER_IDENTITY_TREMOR_SHADER_CODE = """
       shader_type canvas_item;

       uniform sampler2D screen_texture : hint_screen_texture;
       uniform float effect_intensity : hint_range(0.0, 1.0) = 0.0;
       uniform float time_speed : hint_range(0.0, 10.0) = 5.0;

       void fragment() {
       	vec2 uv = SCREEN_UV;

       	// Subtle warp/ghosting
       	float offset_x = sin(uv.y * 20.0 + TIME * time_speed) * 0.005 * effect_intensity;
       	float offset_y = cos(uv.x * 15.0 + TIME * time_speed * 0.7) * 0.005 * effect_intensity;

       	vec2 warped_uv = uv + vec2(offset_x, offset_y);

       	// Desaturation
       	vec4 color = texture(screen_texture, warped_uv);
       	float gray = dot(color.rgb, vec3(0.299, 0.587, 0.114));
       	vec3 desaturated_color = mix(color.rgb, vec3(gray), effect_intensity * 0.5);

       	COLOR = vec4(desaturated_color, color.a);

       	// Optional: Add a subtle color tint for the void effect
       	COLOR.rgb = mix(COLOR.rgb, vec3(0.1, 0.0, 0.2), effect_intensity * 0.3);
       }
       """

       extends CharacterBody3D # Or whatever your player extends

       @onready var _screen_effect_rect: ColorRect = $"../CanvasLayer/ScreenEffectRect" # Adjust path
       var _screen_effect_material: ShaderMaterial

       func _ready() -> void:
       	# Setup screen effect material
       	var screen_shader = Shader.new()
       	screen_shader.code = PLAYER_IDENTITY_TREMOR_SHADER_CODE
       	_screen_effect_material = ShaderMaterial.new()
       	_screen_effect_material.shader = screen_shader
       	_screen_effect_rect.material = _screen_effect_material
       	_screen_effect_material.set_shader_parameter("effect_intensity", 0.0)

       func fire_void_echo(direction: Vector3) -> void:
       	var projectile_instance = VoidEchoProjectile.new()
       	get_tree().root.add_child(projectile_instance) # Or add to a dedicated 'Projectiles' node
       	projectile_instance.global_position = $Muzzle.global_position # Assuming a Muzzle Node3D
       	projectile_instance.initialize(direction, self)
       	projectile_instance.player_identity_tremor.connect(_on_player_identity_tremor)

       func _on_player_identity_tremor(duration: float, intensity: float) -> void:
       	var tween = create_tween()
       	tween.set_ease(Tween.EASE_OUT).set_trans(Tween.TRANS_SINE)
       	tween.tween_property(_screen_effect_material, "shader_parameter/effect_intensity", intensity, duration / 2.0)
       	tween.tween_property(_screen_effect_material, "shader_parameter/effect_intensity", 0.0, duration / 2.0)
       	# Add other debuffs here, e.g., reduced movement speed, visual artifacts on HUD

   b.  **Scene Setup:** In your player scene or main scene, add a `CanvasLayer` node. Inside it, add a `ColorRect` node. Make sure the `ColorRect` covers the entire screen (e.g., `Layout -> Full Rect`). This `ColorRect` will receive the `_screen_effect_material` from the player script.

**2. Enemy Setup (Receiving Impact):**
   a.  **Enemy Script (`Enemy.gd` or similar):**
       gdscript
       extends CharacterBody3D # Or whatever your enemy extends

       @export var max_health: float = 100.0
       var current_health: float
       var _original_material: Material # To store the enemy's original material

       func _ready() -> void:
       	current_health = max_health
       	# Assuming the enemy has a MeshInstance3D child named 'Mesh'
       	if $Mesh is MeshInstance3D:
       		_original_material = $Mesh.get_active_material(0)

       func take_damage(amount: float) -> void:
       	current_health -= amount
       	if current_health <= 0:
       		queue_free() # Or trigger death animation

       func apply_void_impact_effect(material: ShaderMaterial, duration: float) -> void:
       	# Assuming the enemy has a MeshInstance3D child named 'Mesh'
       	if $Mesh is MeshInstance3D:
       		var mesh_instance = $Mesh as MeshInstance3D
       		mesh_instance.material_override = material

       		var tween = create_tween()
       		tween.set_ease(Tween.EASE_OUT).set_trans(Tween.TRANS_SINE)
       		tween.tween_property(material, "shader_parameter/effect_progress", 1.0, duration / 2.0)
       		tween.tween_property(material, "shader_parameter/effect_progress", 0.0, duration / 2.0)
       		tween.tween_callback(func(): 
       			mesh_instance.material_override = _original_material # Restore original material
       		)


**3. Resource Generation:**
   The `void_echo_fired` signal can be connected to a global resource manager or player script to decrement a 'Void Echo' resource count. When Lyra fails to recover a memory fragment or deliberately sacrifices one, this resource can be incremented.
